<script lang="ts">
 import {onDestroy,untrack,tick} from 'svelte';
 import {page} from '$app/state';
 import {goto} from '$app/navigation';
 import {signerIdentity} from '$localLibrary/publication';
 import {createModeratorReports,createModeratorDeletion,moderatorQuery,moderationError,effectDescription,moderatorCategories,moderatorStatuses,type ModeratorContext,type ModeratorPage,type ModeratorDeletionContext} from './moderator-reports';
 let controller:Awaited<ReturnType<typeof createModeratorReports>>|undefined,lifetime:AbortController|undefined;
 let generation=0,disposed=false,busy=$state(false),message=$state(''),account=$state(''),queue=$state<ModeratorPage>(),context=$state<ModeratorContext>(),notes=$state(''),pending=$state(false),review=$state<ReturnType<Awaited<ReturnType<typeof createModeratorReports>>['plan']>>();
 let deletionController:Awaited<ReturnType<typeof createModeratorDeletion>>|undefined;
 let deletion=$state<ModeratorDeletionContext>(),deleteReview=$state<ReturnType<Awaited<ReturnType<typeof createModeratorDeletion>>['plan']>>();
 let category=$state(''),status=$state('waiting'),object=$state(''),reason=$state(''),order=$state('desc'),reportId=$state('');
 function reset(){generation++;lifetime?.abort();lifetime=undefined;controller?.dispose();controller=undefined;deletionController?.dispose();deletionController=undefined;deletion=undefined;deleteReview=undefined;queue=undefined;context=undefined;review=undefined;notes='';account='';pending=false;message='';busy=false;}
 $effect(()=>{const identity=$signerIdentity,route=page.url.href;untrack(()=>{reset();category=page.url.searchParams.get('category')??'';status=page.url.searchParams.get('status')??'';reportId=page.url.searchParams.get('reportId')??'';object=page.url.searchParams.get('object')??'';reason=page.url.searchParams.get('reason')??'';order=page.url.searchParams.get('order')??'desc';});});
 onDestroy(()=>{disposed=true;reset();});
 function capture(){const token=generation,href=window.location.href;return()=>{if(disposed||token!==generation||window.location.href!==href)throw Error('Moderation view changed');};}
 async function load(){if(busy||!$signerIdentity.owner)return;reset();const check=capture(),token=generation,input=new URLSearchParams(page.url.search);busy=true;lifetime=new AbortController();try{const selection=moderatorQuery(input);if(selection.query.get('intent')==='delete'&&selection.reportId){const next=await createModeratorDeletion(check,{},lifetime.signal);try{check();}catch(error){next.dispose();throw error;}deletionController=next;deletion=await next.read(selection.reportId);check();account=`${next.account.name} (${next.account.id})`;pending=next.pending(selection.reportId);return;}const next=await createModeratorReports(check,{},lifetime.signal);try{check();}catch(error){next.dispose();throw error;}controller=next;const result=await next.read(input);check();account=`${next.account.name} (${next.account.id})`;if('report' in result){context=result;pending=next.pending(result.report.id);}else queue=result;}catch(error){if(!disposed&&token===generation){controller?.dispose();controller=undefined;deletionController?.dispose();deletionController=undefined;deletion=undefined;deleteReview=undefined;queue=undefined;context=undefined;message=moderationError(error);}}finally{if(!disposed&&token===generation)busy=false;}}
 async function navigate(input:URLSearchParams){const href='/reports/moderation'+(input.size?'?'+input:'');reset();await goto(href);await tick();if(!disposed&&window.location.pathname+window.location.search===href)await load();}
 async function filter(event:SubmitEvent){event.preventDefault();const input=new URLSearchParams();if(category)input.set('category',category);if(status)input.set('status',status);if(object)input.set('object',object);if(reason)input.set('reason',reason);if(order!=='desc')input.set('order',order);await navigate(input);}
 async function lookup(event:SubmitEvent){event.preventDefault();await navigate(new URLSearchParams({reportId}));}
 function plan(action:'accept'|'refuse'){if(!controller||!context||busy||pending)return;try{review=controller.plan(action,notes);message='';}catch(error){message=moderationError(error);}}
 async function submit(){if(!controller||!context||!review||busy||pending)return;const owner=controller,prepared=review,token=generation,check=capture(),id=context.report.id;review=undefined;busy=true;try{const receipt=await owner.submit(prepared);check();context=undefined;notes='';message=`Report ${id} ${receipt.status}. Exact decision and instance effect confirmed; original protocol events were not changed.`;}catch(error){if(!disposed&&token===generation){context=undefined;notes='';message=moderationError(error);}}finally{if(!disposed&&token===generation){try{pending=owner.pending(id);}catch{pending=true;}busy=false;}}}
 function planDelete(){if(!deletionController||!deletion||busy||pending)return;try{deleteReview=deletionController.plan();message='';}catch(error){message=moderationError(error);}}
 async function submitDelete(){if(!deletionController||!deletion||!deleteReview||busy||pending)return;const owner=deletionController,prepared=deleteReview,token=generation,check=capture(),id=deletion.report.id;deleteReview=undefined;busy=true;try{await owner.submit(prepared);check();deletion=undefined;message=`Report ${id} deleted from native report lists. Report status and audit history were preserved; reported content and protocol events were not changed.`;}catch(error){if(!disposed&&token===generation){deletion=undefined;message=moderationError(error);}}finally{if(!disposed&&token===generation){try{pending=owner.pending(id);}catch{pending=true;}busy=false;}}}
 function next(){if(queue?.nextCursor){const input=new URLSearchParams(page.url.search);input.set('cursor',queue.nextCursor);void navigate(input);}}
</script>
<svelte:head><title>Signed Instance Moderation</title></svelte:head>
<section class="space-y-5">
 <h2 class="text-xl font-medium">Signed Instance Moderation</h2>
 <p>Explicit moderator access for the selected signing identity’s bound account. A browser login, report ownership or personal inspection never grants moderator permission.</p>
 <nav class="flex gap-3"><a class="underline" href="/reports/signed/native">My signed native reports</a><a class="underline" href="/my/reports">Browser-login reports</a><a class="underline" href="/settings/identity">Identity settings</a></nav>
 {#if !$signerIdentity.owner}<p>Select a signing identity before opening private moderation.</p>{/if}
 <form class="flex flex-wrap gap-3" onsubmit={filter}><label>Category <select aria-label="Moderation category" bind:value={category} disabled={busy||!!review||!!deleteReview}><option value="">All native categories</option>{#each moderatorCategories as value}<option {value}>{value}</option>{/each}</select></label><label>Status <select aria-label="Moderation status" bind:value={status} disabled={busy||!!review||!!deleteReview}><option value="">All statuses</option>{#each moderatorStatuses as value}<option {value}>{value}</option>{/each}</select></label><label>Native object ID <input aria-label="Moderation object ID" bind:value={object} maxlength="128" disabled={busy||!!review||!!deleteReview}/></label><label>Native reason ID <input aria-label="Moderation reason ID" bind:value={reason} maxlength="128" disabled={busy||!!review||!!deleteReview}/></label><label>Order <select aria-label="Moderation order" bind:value={order} disabled={busy||!!review||!!deleteReview}><option value="desc">Newest first</option><option value="asc">Oldest first</option></select></label><button type="submit" disabled={busy||!!review||!!deleteReview||!$signerIdentity.owner}>Apply moderation filters</button></form>
 <form class="flex gap-3" onsubmit={lookup}><label>Native report ID <input aria-label="Moderation report ID" bind:value={reportId} maxlength="128" disabled={busy||!!review||!!deleteReview}/></label><button type="submit" disabled={busy||!!review||!!deleteReview||!$signerIdentity.owner||!reportId}>Open report by ID</button><button type="button" disabled={busy||!!review||!!deleteReview||!$signerIdentity.owner||!reportId} onclick={()=>navigate(new URLSearchParams({reportId,intent:'delete'}))}>Review deletion by ID</button></form>
 <button type="button" disabled={busy||!!review||!!deleteReview||!$signerIdentity.owner} onclick={load}>Load signed moderation</button>
 {#if busy}<button type="button" onclick={()=>{reset();message='View closed. Any dispatched decision remains protected against repetition.';}}>Close moderation view</button><p role="status">Checking signed moderation…</p>{/if}
 {#if account}<p>Reviewing as {account}.</p>{/if}
 {#if message}<p role="alert">{message}</p>{/if}
 {#if pending}<p role="alert">An unconfirmed decision is protected against repetition. Reading this report again never clears that safeguard. Ask the instance operator to reconcile it.</p>{/if}
 {#if queue}<p>{queue.total} reports match this live snapshot. Each page contains at most five summaries; continuation has no offset ceiling.</p><ul>{#each queue.data as row (row.id)}<li class="border-t py-3"><p>{row.status} · {row.category} · native report {row.id} · revision {row.version}</p><p>Subject {row.objectId}; submitter {row.submitterId}; reason {row.reasonId}.</p><button type="button" disabled={busy} onclick={()=>navigate(new URLSearchParams({reportId:row.id}))}>Review report {row.id}</button><button type="button" disabled={busy} onclick={()=>navigate(new URLSearchParams({reportId:row.id,intent:'delete'}))}>Delete Report {row.id}</button><button type="button" disabled={busy} onclick={()=>{const q=new URLSearchParams(page.url.search);q.delete('cursor');q.set('category',row.category);q.set('object',row.objectId);void navigate(q);}}>Filter this object</button></li>{/each}</ul>{#if !queue.data.length}<p>No reports were returned for this selection. This does not resolve an uncertain decision.</p>{/if}<button type="button" disabled={busy||!queue.nextCursor} onclick={next}>Next moderation reports</button>{#if page.url.searchParams.has('cursor')}<button type="button" disabled={busy} onclick={()=>{const q=new URLSearchParams(page.url.search);q.delete('cursor');void navigate(q);}}>First matching reports</button>{/if}{/if}
 {#if context}
  <section class="space-y-3 border p-3" aria-label="Native moderation context"><h3>Native report {context.report.id}: {context.report.status}</h3><p>Report revision {context.report.version}, current reason revision {context.reason.version}. Submitter: {context.report.submitterId}.</p><p>Reason: {context.reason.label}</p><p class="whitespace-pre-wrap">{context.report.details||'No submitted details.'}</p>{#if context.report.notes}<p class="whitespace-pre-wrap">Existing moderator notes: {context.report.notes}</p>{/if}
   <p>Native {context.report.category} subject: {context.report.objectId}. {context.target.available?'Currently available':'Historical or unavailable target; no hidden content is shown'}.</p>{#if context.target.available}<p>{String(context.target.label||'')}</p><p class="whitespace-pre-wrap">{String(context.target.body||'')}</p>{/if}
   {#if context.claimant}<p>Claimant: {String(context.claimant.name)} ({String(context.claimant.id)}), current revision {String(context.claimant.version)}. {context.claimant.eligible?'Currently eligible':'No longer eligible'}.</p>{/if}
   {#if context.report.status==='waiting'&&!pending}<label>Moderator notes <textarea aria-label="Moderator notes" bind:value={notes} maxlength="20000" disabled={busy||!!review||!!deleteReview}></textarea></label><div class="flex gap-3"><button type="button" disabled={busy||!!review||!!deleteReview||!context.acceptAllowed} onclick={()=>plan('accept')}>Review acceptance</button><button type="button" disabled={busy||!!review||!!deleteReview} onclick={()=>plan('refuse')}>Review refusal</button></div>{#if !context.acceptAllowed}<p>Acceptance is not currently permitted for this exact target, revision or moderator grant. Refusal does not perform the proposed content or membership effect.</p>{/if}{/if}
  </section>
 {/if}
 {#if deletion}
  <section class="space-y-3 border p-3" aria-label="Report-only deletion context"><h3>Delete Report {deletion.report.id}</h3><p>Current status: {deletion.report.status}; report revision {deletion.report.version}. Native {deletion.report.category} object {deletion.report.objectId}; reason {deletion.report.reasonId}.</p><p>This hides only the report from native report lists. Prior status, notes and audit history are preserved. Reported content, membership, original protocol events and peer copies are not deleted or changed. No hidden target content is loaded.</p><button type="button" disabled={busy||pending||!!deleteReview} onclick={planDelete}>Review Delete Report consequence</button></section>
 {/if}
 {#if deleteReview&&deletion}<section class="space-y-3 border p-3" aria-label="Confirm signed report deletion"><h3>Confirm Delete Report as {account}</h3><p>Delete native report {deletion.report.id}, revision {deleteReview.expectedReportVersion}, using account revision {deletion.authority.version}. This changes only the report deletion marker and revision, retaining status {deletion.report.status}, prior notes and audit history. It does not delete reported content or protocol events.</p><button type="button" disabled={busy||pending} onclick={submitDelete}>Confirm Delete Report</button><button type="button" disabled={busy} onclick={()=>deleteReview=undefined}>Cancel deletion review</button></section>{/if}
 {#if review&&context}<section class="space-y-3 border p-3" aria-label="Confirm signed moderator decision"><h3>Confirm {review.action} as {account}</h3><p>Native report {context.report.id}, report revision {review.expectedReportVersion}, reason revision {review.expectedReasonVersion}.</p><p>{effectDescription(context,review.action)}</p><p class="whitespace-pre-wrap">Exact notes: {review.notes||'(none)'}</p><button type="button" disabled={busy} onclick={submit}>Confirm signed decision</button><button type="button" disabled={busy} onclick={()=>review=undefined}>Cancel decision review</button></section>{/if}
</section>
